package paradox.dl;
import org.junit.*;import static org.junit.Assert.*;import java.io.*;import java.nio.file.*;import java.net.*;import java.util.*;import com.sun.net.httpserver.*;
public class EngineDirectoryTest {
 @Test public void nonexistentParentsAreCreatedBeforeCompleteTransfer()throws Exception{
  final byte[] data=new byte[73791];new Random(13).nextBytes(data);File root=Files.createTempDirectory("dl13-").toFile();final File target=new File(root,"no-backup/ultra_audio_parts/song.part");assertFalse(target.getParentFile().exists());HttpServer server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);
  server.createContext("/audio",e->{String range=e.getRequestHeaders().getFirst("Range");String[] pair=range.substring(6).split("-");int start=Integer.parseInt(pair[0]),end=Integer.parseInt(pair[1]);e.getResponseHeaders().add("Content-Type","audio/mp4");e.getResponseHeaders().add("Content-Range","bytes "+start+"-"+end+"/"+data.length);e.sendResponseHeaders(206,end-start+1);try(OutputStream o=e.getResponseBody()){o.write(data,start,end-start+1);}});server.start();final String url="http://127.0.0.1:"+server.getAddress().getPort()+"/audio";
  try{Engine engine=new Engine();engine.run(new Engine.UrlSource(){public String url(int p){return url;}public String refresh(int p){return url;}},new long[]{data.length},new File[]{target});assertTrue(target.isFile());assertArrayEquals(data,Files.readAllBytes(target.toPath()));assertEquals(data.length,engine.done.get());assertFalse(Engine.mapFile(target).exists());}finally{server.stop(0);}
 }
 @Test public void blockedParentReportsExactPath()throws Exception{File root=Files.createTempDirectory("dl13-block-").toFile(),block=new File(root,"blocked");assertTrue(block.createNewFile());try{Engine.prepare(new File(block,"song.part"));fail();}catch(Engine.FileFailure e){assertTrue(e.getMessage().contains(block.getAbsolutePath()));assertTrue(ultra.downloads.ResolveErrors.describe(e).contains(block.getAbsolutePath()));}}
 @Test public void nestedErrnoRetainsPath(){File f=new File("/app-private/ultra_audio_parts/song.part.map");Engine.FileFailure e=new Engine.FileFailure("Prepare transfer file",f,new IOException("open failed",new IOException("ENOENT")));String text=ultra.downloads.ResolveErrors.describe(e);assertTrue(text.contains(f.getPath()));assertTrue(text.contains("open failed"));}
 @Test public void mapDirectoryFailsWithItsPathAndCanBeRetried()throws Exception{File root=Files.createTempDirectory("dl13-map-").toFile(),target=new File(root,"song.part"),map=Engine.mapFile(target);assertTrue(map.mkdir());assertTrue(new File(map,"keep").createNewFile());try{new Engine().run(new Engine.UrlSource(){public String url(int p){return "http://unused.invalid/audio";}public String refresh(int p){return "";}},new long[]{50},new File[]{target});fail();}catch(Engine.FileFailure e){assertTrue(e.getMessage().contains(map.getAbsolutePath()));}assertTrue(new File(map,"keep").delete());assertTrue(map.delete());Engine.prepare(target);try(RandomAccessFile file=new RandomAccessFile(target,"rw")){file.write(1);}assertEquals(1,target.length());}
}
